"""Offline synchronous left/right review of real baked frames, no mirroring."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
PAGE='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>左右步行同步对照</title><style>body{font:16px system-ui;background:#202830;color:#eee;margin:28px}main{display:flex;gap:20px;flex-wrap:wrap}canvas{background:#dcd7ca;image-rendering:pixelated}button,input{font:inherit;margin:8px;padding:8px}a{color:#b1dfff}small{color:#bbc6cc}</style><h1>左右步行同步对照</h1><p>同一相位、同一75%速度；四个画面均加载各自真实纹理，没有显示时镜像。</p><button id="play">暂停</button><button id="next">下一帧</button><button id="bg">明暗背景</button><input id="speed" type="range" min="50" max="100" value="75"><span id="rate">75%</span><main id="grid"></main><p id="pose"></p><p><a href="review.html">四向 / 站立 / 换衣评审</a> · <a href="launch-game-trial.command">港口试玩入口</a></p><small>此处放大检视；游戏内人物约138渲染像素高。新稿姿态已统一，细小绘制差异仍需实际观感评审，不宣称像素镜像或严格脚点锁定。</small><p><small id="hash"></small></p><script>const m=MANIFEST;
let elapsed=0,last=performance.now(),playing=true,dark=false;const panels=[];
for(const garment of ['A','B'])for(const direction of ['west','east']){const block=document.createElement('div');const title=document.createElement('p');title.textContent=(garment==='A'?'奶油短袖':'蓝色长袖')+' · '+(direction==='west'?'向左':'向右');const c=document.createElement('canvas');c.width=256;c.height=384;block.append(title,c);document.getElementById('grid').append(block);const frames=m.actions.walk.directions[direction].map(id=>{const f=m.recipes[garment].frames.find(x=>x.pose_id===id),im=new Image();im.src='baked/'+f.file;return im});panels.push({c,frames})}
const speed=document.getElementById('speed');function loop(now){if(playing)elapsed+=(now-last)*Number(speed.value)/100;last=now;let frame=Math.floor(elapsed/80)%4;for(const {c,frames} of panels){const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,256,384);const im=frames[frame];if(im.complete&&im.naturalWidth)ctx.drawImage(im,0,0,256,384)}document.getElementById('pose').textContent='相位 '+frame+' / 3 · '+(80/(Number(speed.value)/100)).toFixed(1)+' ms/帧';requestAnimationFrame(loop)}
document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'暂停':'播放'};document.getElementById('next').onclick=()=>{playing=false;elapsed=(Math.floor(elapsed/80)+1)*80;document.getElementById('play').textContent='播放'};document.getElementById('bg').onclick=()=>{dark=!dark;for(const {c} of panels)c.style.background=dark?'#14202b':'#dcd7ca'};speed.oninput=()=>document.getElementById('rate').textContent=speed.value+'%';document.getElementById('hash').textContent='artifact '+m.artifact_digest;requestAnimationFrame(loop);
</script></html>'''
if __name__=='__main__':
 m=json.loads((ROOT/'baked/export-manifest.json').read_text());data={k:m[k] for k in ['actions','recipes','artifact_digest']};(ROOT/'symmetry-review.html').write_text(PAGE.replace('MANIFEST',json.dumps(data,ensure_ascii=False).replace('</','<\\/')))
 print('Symmetry review binds',m['artifact_digest'])
